{

    internal InnerCodeSecurityScanConfigurationContinuousIntegrationScanConfigurationFactory continuousIntegrationScanConfigurationFactory { get; set; }

    internal InnerCodeSecurityScanConfigurationPeriodicScanConfigurationFactory periodicScanConfigurationFactory { get; set; }

    protected override Humidifier.InspectorV2.CodeSecurityScanConfigurationTypes.CodeSecurityScanConfiguration Create()
    {
        var codeSecurityScanConfigurationResult = CreateCodeSecurityScanConfiguration();
        factoryAction?.Invoke(codeSecurityScanConfigurationResult);

        return codeSecurityScanConfigurationResult;
    }

    private Humidifier.InspectorV2.CodeSecurityScanConfigurationTypes.CodeSecurityScanConfiguration CreateCodeSecurityScanConfiguration()
    {
        var codeSecurityScanConfigurationResult = new Humidifier.InspectorV2.CodeSecurityScanConfigurationTypes.CodeSecurityScanConfiguration();

        return codeSecurityScanConfigurationResult;
    }
    public override void CreateChildren(Humidifier.InspectorV2.CodeSecurityScanConfigurationTypes.CodeSecurityScanConfiguration result)
    {
        base.CreateChildren(result);

        result.continuousIntegrationScanConfiguration ??= continuousIntegrationScanConfigurationFactory?.Build();
        result.periodicScanConfiguration ??= periodicScanConfigurationFactory?.Build();
    }

} // End Of Class

